/* Reset ONLY ProductCode T588880028, across all warehouses and locations.
   Default is PREVIEW. Does not delete or alter dbMaster Master data.
   Stop WH Stock service and back up dbWMS before execution.
   Mixed-product connected documents cause execution to STOP, never delete other SKUs.
   No identity reseed or shared document numbering reset for a single-product reset.
*/
USE [dbWMS];
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @ProductCode nvarchar(50)=N'T588880028';
DECLARE @Execute bit=0; -- 0: preview only; 1: execute with backup snapshots
DECLARE @Confirmation nvarchar(100)=N''; -- execution requires RESET:T588880028
DECLARE @ProductId int,@Added int,@Loops int=0,@RunId uniqueidentifier=NEWID();
IF @@TRANCOUNT<>0 THROW 51000,N'Run in a new query window without an existing transaction.',1;
IF (SELECT COUNT(*) FROM dbMaster.dbo.tblProducts WHERE ProductCode=@ProductCode)<>1
 THROW 51000,N'ProductCode must resolve to exactly one ProductId.',1;
SELECT @ProductId=ProductId FROM dbMaster.dbo.tblProducts WHERE ProductCode=@ProductCode;
IF @Execute=1 AND @Confirmation<>N'RESET:'+@ProductCode THROW 51000,N'Confirmation does not match the selected ProductCode.',1;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @LockResult int;
EXEC @LockResult=sys.sp_getapplock @Resource=N'WHStock_ProductReset',@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=10000;
IF @LockResult<0 THROW 51000,N'Could not obtain reset lock. Nothing deleted.',1;

IF EXISTS(SELECT 1 FROM sys.tables t WHERE t.is_ms_shipped=0 AND (SCHEMA_NAME(t.schema_id)<>'dbo' OR (t.name NOT IN (N'CheckAudit',N'CheckContainers',N'CheckItems',N'CheckSessions',N'DeliveryAudit',N'DeliveryContainers',N'DeliveryCustody',N'DeliveryLines',N'DeliveryOrders',N'DeliveryPlans',N'InboundCancelAudit',N'InboundLines',N'InboundManufacturerLinks',N'InboundOrders',N'InboundPlans',N'InboundProductionInfo',N'InboundReceipts',N'InventoryCountItems',N'InventoryCountSessions',N'PickOperations',N'PurchaseOrderLines',N'PurchaseOrders',N'RMContainerEvents',N'RMContainers',N'RMInboundPacks',N'RMSubRequests',N'RMSubTransferAudit',N'RMSubTransferContainers',N'RMSubTransfers',N'StockTransfers',N'StorageMoves',N'StoragePlanLines',N'StoragePlans',N'tblStock',N'tblStockTransactions',N'DeliveryNumberSeries') AND t.name NOT IN (N'ProductResetAudit',N'ProductResetBackup')))) THROW 51000,N'Unexpected table/schema detected. Update reset script before use.',1;
IF EXISTS(SELECT 1 FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id WHERE c.name='ProductId' AND t.name NOT IN (N'CheckAudit',N'CheckContainers',N'CheckItems',N'CheckSessions',N'DeliveryAudit',N'DeliveryContainers',N'DeliveryCustody',N'DeliveryLines',N'DeliveryOrders',N'DeliveryPlans',N'InboundCancelAudit',N'InboundLines',N'InboundManufacturerLinks',N'InboundOrders',N'InboundPlans',N'InboundProductionInfo',N'InboundReceipts',N'InventoryCountItems',N'InventoryCountSessions',N'PickOperations',N'PurchaseOrderLines',N'PurchaseOrders',N'RMContainerEvents',N'RMContainers',N'RMInboundPacks',N'RMSubRequests',N'RMSubTransferAudit',N'RMSubTransferContainers',N'RMSubTransfers',N'StockTransfers',N'StorageMoves',N'StoragePlanLines',N'StoragePlans',N'tblStock',N'tblStockTransactions') AND t.name NOT LIKE 'ProductReset%') THROW 51000,N'New ProductId table detected. Update reset script before use.',1;
IF EXISTS(SELECT 1 FROM sys.foreign_keys f JOIN sys.foreign_key_columns fc ON fc.constraint_object_id=f.object_id WHERE NOT EXISTS(SELECT 1 FROM (VALUES (N'DeliveryLines',N'DeliveryId',N'DeliveryOrders',N'DeliveryId'),(N'DeliveryContainers',N'DeliveryId',N'DeliveryOrders',N'DeliveryId'),(N'DeliveryAudit',N'DeliveryId',N'DeliveryOrders',N'DeliveryId'),(N'PurchaseOrderLines',N'PurchaseOrderId',N'PurchaseOrders',N'PurchaseOrderId'),(N'DeliveryCustody',N'LineId',N'DeliveryLines',N'LineId'),(N'InventoryCountItems',N'SessionId',N'InventoryCountSessions',N'SessionId'),(N'DeliveryOrders',N'PlanId',N'DeliveryPlans',N'PlanId'),(N'InboundOrders',N'PlanId',N'InboundPlans',N'PlanId'),(N'RMContainerEvents',N'ContainerId',N'RMContainers',N'ContainerId'),(N'CheckContainers',N'ContainerId',N'RMContainers',N'ContainerId'),(N'DeliveryContainers',N'ContainerId',N'RMContainers',N'ContainerId'),(N'RMSubTransferContainers',N'ContainerId',N'RMContainers',N'ContainerId'),(N'CheckItems',N'SessionId',N'CheckSessions',N'Id'),(N'CheckAudit',N'SessionId',N'CheckSessions',N'Id'),(N'CheckContainers',N'ItemId',N'CheckItems',N'Id'),(N'PurchaseOrders',N'InboundId',N'InboundOrders',N'InboundId'),(N'InboundProductionInfo',N'InboundId',N'InboundOrders',N'InboundId'),(N'InboundCancelAudit',N'InboundId',N'InboundOrders',N'InboundId'),(N'InboundLines',N'InboundId',N'InboundOrders',N'InboundId'),(N'RMInboundPacks',N'LineId',N'InboundLines',N'LineId'),(N'InboundManufacturerLinks',N'LineId',N'InboundLines',N'LineId'),(N'InboundReceipts',N'LineId',N'InboundLines',N'LineId'),(N'RMContainers',N'InboundReceiptId',N'InboundReceipts',N'ReceiptId'),(N'StoragePlanLines',N'PlanId',N'StoragePlans',N'PlanId'),(N'StorageMoves',N'LineId',N'StoragePlanLines',N'LineId'),(N'RMSubTransferAudit',N'TransferId',N'RMSubTransfers',N'TransferId'),(N'RMSubRequests',N'TransferId',N'RMSubTransfers',N'TransferId'),(N'RMSubTransferContainers',N'TransferId',N'RMSubTransfers',N'TransferId'),(N'RMContainerEvents',N'PickId',N'PickOperations',N'PickId')) v(CT,CC,PT,PC) WHERE v.CT=OBJECT_NAME(f.parent_object_id) AND v.CC=COL_NAME(f.parent_object_id,fc.parent_column_id) AND v.PT=OBJECT_NAME(f.referenced_object_id) AND v.PC=COL_NAME(f.referenced_object_id,fc.referenced_column_id))) THROW 51000,N'New foreign key detected. Update reset script before use.',1;
CREATE TABLE #r_CheckAudit([Id] int NOT NULL, PRIMARY KEY([Id]));
CREATE TABLE #r_CheckContainers([Id] int NOT NULL, PRIMARY KEY([Id]));
CREATE TABLE #r_CheckItems([Id] int NOT NULL, PRIMARY KEY([Id]));
CREATE TABLE #r_CheckSessions([Id] int NOT NULL, PRIMARY KEY([Id]));
CREATE TABLE #r_DeliveryAudit([AuditId] int NOT NULL, PRIMARY KEY([AuditId]));
CREATE TABLE #r_DeliveryContainers([DeliveryId] int NOT NULL, [ContainerId] int NOT NULL, PRIMARY KEY([DeliveryId],[ContainerId]));
CREATE TABLE #r_DeliveryCustody([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_DeliveryLines([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_DeliveryOrders([DeliveryId] int NOT NULL, PRIMARY KEY([DeliveryId]));
CREATE TABLE #r_DeliveryPlans([PlanId] int NOT NULL, PRIMARY KEY([PlanId]));
CREATE TABLE #r_InboundCancelAudit([InboundId] int NOT NULL, PRIMARY KEY([InboundId]));
CREATE TABLE #r_InboundLines([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_InboundManufacturerLinks([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_InboundOrders([InboundId] int NOT NULL, PRIMARY KEY([InboundId]));
CREATE TABLE #r_InboundPlans([PlanId] int NOT NULL, PRIMARY KEY([PlanId]));
CREATE TABLE #r_InboundProductionInfo([InboundId] int NOT NULL, PRIMARY KEY([InboundId]));
CREATE TABLE #r_InboundReceipts([ReceiptId] int NOT NULL, PRIMARY KEY([ReceiptId]));
CREATE TABLE #r_InventoryCountItems([ItemId] int NOT NULL, PRIMARY KEY([ItemId]));
CREATE TABLE #r_InventoryCountSessions([SessionId] int NOT NULL, PRIMARY KEY([SessionId]));
CREATE TABLE #r_PickOperations([PickId] int NOT NULL, PRIMARY KEY([PickId]));
CREATE TABLE #r_PurchaseOrderLines([PurchaseOrderLineId] int NOT NULL, PRIMARY KEY([PurchaseOrderLineId]));
CREATE TABLE #r_PurchaseOrders([PurchaseOrderId] int NOT NULL, PRIMARY KEY([PurchaseOrderId]));
CREATE TABLE #r_RMContainerEvents([EventId] bigint NOT NULL, PRIMARY KEY([EventId]));
CREATE TABLE #r_RMContainers([ContainerId] int NOT NULL, PRIMARY KEY([ContainerId]));
CREATE TABLE #r_RMInboundPacks([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_RMSubRequests([RequestId] int NOT NULL, PRIMARY KEY([RequestId]));
CREATE TABLE #r_RMSubTransferAudit([AuditId] int NOT NULL, PRIMARY KEY([AuditId]));
CREATE TABLE #r_RMSubTransferContainers([TransferId] int NOT NULL, [ContainerId] int NOT NULL, PRIMARY KEY([TransferId],[ContainerId]));
CREATE TABLE #r_RMSubTransfers([TransferId] int NOT NULL, PRIMARY KEY([TransferId]));
CREATE TABLE #r_StockTransfers([TransferId] int NOT NULL, PRIMARY KEY([TransferId]));
CREATE TABLE #r_StorageMoves([MoveId] int NOT NULL, PRIMARY KEY([MoveId]));
CREATE TABLE #r_StoragePlanLines([LineId] int NOT NULL, PRIMARY KEY([LineId]));
CREATE TABLE #r_StoragePlans([PlanId] int NOT NULL, PRIMARY KEY([PlanId]));
CREATE TABLE #r_tblStock([StockId] int NOT NULL, PRIMARY KEY([StockId]));
CREATE TABLE #r_tblStockTransactions([TransId] int NOT NULL, PRIMARY KEY([TransId]));
INSERT #r_CheckItems SELECT p.[Id] FROM dbo.[CheckItems] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_DeliveryLines SELECT p.[LineId] FROM dbo.[DeliveryLines] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_InboundLines SELECT p.[LineId] FROM dbo.[InboundLines] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_InventoryCountItems SELECT p.[ItemId] FROM dbo.[InventoryCountItems] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_PickOperations SELECT p.[PickId] FROM dbo.[PickOperations] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_PurchaseOrderLines SELECT p.[PurchaseOrderLineId] FROM dbo.[PurchaseOrderLines] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_RMContainers SELECT p.[ContainerId] FROM dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_RMSubRequests SELECT p.[RequestId] FROM dbo.[RMSubRequests] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_RMSubTransfers SELECT p.[TransferId] FROM dbo.[RMSubTransfers] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_StockTransfers SELECT p.[TransferId] FROM dbo.[StockTransfers] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_StoragePlans SELECT p.[PlanId] FROM dbo.[StoragePlans] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_tblStock SELECT p.[StockId] FROM dbo.[tblStock] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_tblStockTransactions SELECT p.[TransId] FROM dbo.[tblStockTransactions] p WITH(UPDLOCK,HOLDLOCK) WHERE p.ProductId=@ProductId;
INSERT #r_DeliveryPlans SELECT p.[PlanId] FROM dbo.[DeliveryPlans] p WITH(UPDLOCK,HOLDLOCK) WHERE EXISTS(SELECT 1 FROM OPENJSON(p.Payload,'$.lines') WITH(productId int '$.productId',ProductIdUpper int '$.ProductId') j WHERE COALESCE(j.productId,j.ProductIdUpper)=@ProductId);
INSERT #r_InboundPlans SELECT p.[PlanId] FROM dbo.[InboundPlans] p WITH(UPDLOCK,HOLDLOCK) WHERE EXISTS(SELECT 1 FROM OPENJSON(p.Payload,'$.lines') WITH(productId int '$.productId',ProductIdUpper int '$.ProductId') j WHERE COALESCE(j.productId,j.ProductIdUpper)=@ProductId);
-- Follow FK connections in both directions. Complete documents must be consistent.
WHILE 1=1 BEGIN
 SET @Added=0;SET @Loops+=1;
 IF @Loops>100 THROW 51000,N'Dependency traversal exceeded limit.',1;
 INSERT #r_DeliveryLines SELECT DISTINCT c.[LineId] FROM dbo.[DeliveryLines] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryOrders k ON p.[DeliveryId]=k.[DeliveryId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryLines x WHERE c.[LineId]=x.[LineId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryOrders SELECT DISTINCT p.[DeliveryId] FROM dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryLines] c WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryLines k ON c.[LineId]=k.[LineId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryOrders x WHERE p.[DeliveryId]=x.[DeliveryId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryContainers SELECT DISTINCT c.[DeliveryId], c.[ContainerId] FROM dbo.[DeliveryContainers] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryOrders k ON p.[DeliveryId]=k.[DeliveryId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryContainers x WHERE c.[DeliveryId]=x.[DeliveryId] AND c.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryOrders SELECT DISTINCT p.[DeliveryId] FROM dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryContainers] c WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryContainers k ON c.[DeliveryId]=k.[DeliveryId] AND c.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryOrders x WHERE p.[DeliveryId]=x.[DeliveryId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryAudit SELECT DISTINCT c.[AuditId] FROM dbo.[DeliveryAudit] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryOrders k ON p.[DeliveryId]=k.[DeliveryId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryAudit x WHERE c.[AuditId]=x.[AuditId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryOrders SELECT DISTINCT p.[DeliveryId] FROM dbo.[DeliveryOrders] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryAudit] c WITH(UPDLOCK,HOLDLOCK) ON c.[DeliveryId]=p.[DeliveryId] JOIN #r_DeliveryAudit k ON c.[AuditId]=k.[AuditId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryOrders x WHERE p.[DeliveryId]=x.[DeliveryId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_PurchaseOrderLines SELECT DISTINCT c.[PurchaseOrderLineId] FROM dbo.[PurchaseOrderLines] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[PurchaseOrders] p WITH(UPDLOCK,HOLDLOCK) ON c.[PurchaseOrderId]=p.[PurchaseOrderId] JOIN #r_PurchaseOrders k ON p.[PurchaseOrderId]=k.[PurchaseOrderId] WHERE NOT EXISTS(SELECT 1 FROM #r_PurchaseOrderLines x WHERE c.[PurchaseOrderLineId]=x.[PurchaseOrderLineId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_PurchaseOrders SELECT DISTINCT p.[PurchaseOrderId] FROM dbo.[PurchaseOrders] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[PurchaseOrderLines] c WITH(UPDLOCK,HOLDLOCK) ON c.[PurchaseOrderId]=p.[PurchaseOrderId] JOIN #r_PurchaseOrderLines k ON c.[PurchaseOrderLineId]=k.[PurchaseOrderLineId] WHERE NOT EXISTS(SELECT 1 FROM #r_PurchaseOrders x WHERE p.[PurchaseOrderId]=x.[PurchaseOrderId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryCustody SELECT DISTINCT c.[LineId] FROM dbo.[DeliveryCustody] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryLines] p WITH(UPDLOCK,HOLDLOCK) ON c.[LineId]=p.[LineId] JOIN #r_DeliveryLines k ON p.[LineId]=k.[LineId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryCustody x WHERE c.[LineId]=x.[LineId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryLines SELECT DISTINCT p.[LineId] FROM dbo.[DeliveryLines] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryCustody] c WITH(UPDLOCK,HOLDLOCK) ON c.[LineId]=p.[LineId] JOIN #r_DeliveryCustody k ON c.[LineId]=k.[LineId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryLines x WHERE p.[LineId]=x.[LineId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_InventoryCountItems SELECT DISTINCT c.[ItemId] FROM dbo.[InventoryCountItems] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[InventoryCountSessions] p WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[SessionId] JOIN #r_InventoryCountSessions k ON p.[SessionId]=k.[SessionId] WHERE NOT EXISTS(SELECT 1 FROM #r_InventoryCountItems x WHERE c.[ItemId]=x.[ItemId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_InventoryCountSessions SELECT DISTINCT p.[SessionId] FROM dbo.[InventoryCountSessions] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[InventoryCountItems] c WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[SessionId] JOIN #r_InventoryCountItems k ON c.[ItemId]=k.[ItemId] WHERE NOT EXISTS(SELECT 1 FROM #r_InventoryCountSessions x WHERE p.[SessionId]=x.[SessionId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryOrders SELECT DISTINCT c.[DeliveryId] FROM dbo.[DeliveryOrders] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryPlans] p WITH(UPDLOCK,HOLDLOCK) ON c.[PlanId]=p.[PlanId] JOIN #r_DeliveryPlans k ON p.[PlanId]=k.[PlanId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryOrders x WHERE c.[DeliveryId]=x.[DeliveryId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryPlans SELECT DISTINCT p.[PlanId] FROM dbo.[DeliveryPlans] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryOrders] c WITH(UPDLOCK,HOLDLOCK) ON c.[PlanId]=p.[PlanId] JOIN #r_DeliveryOrders k ON c.[DeliveryId]=k.[DeliveryId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryPlans x WHERE p.[PlanId]=x.[PlanId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_InboundOrders SELECT DISTINCT c.[InboundId] FROM dbo.[InboundOrders] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[InboundPlans] p WITH(UPDLOCK,HOLDLOCK) ON c.[PlanId]=p.[PlanId] JOIN #r_InboundPlans k ON p.[PlanId]=k.[PlanId] WHERE NOT EXISTS(SELECT 1 FROM #r_InboundOrders x WHERE c.[InboundId]=x.[InboundId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_InboundPlans SELECT DISTINCT p.[PlanId] FROM dbo.[InboundPlans] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[InboundOrders] c WITH(UPDLOCK,HOLDLOCK) ON c.[PlanId]=p.[PlanId] JOIN #r_InboundOrders k ON c.[InboundId]=k.[InboundId] WHERE NOT EXISTS(SELECT 1 FROM #r_InboundPlans x WHERE p.[PlanId]=x.[PlanId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMContainerEvents SELECT DISTINCT c.[EventId] FROM dbo.[RMContainerEvents] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMContainers k ON p.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_RMContainerEvents x WHERE c.[EventId]=x.[EventId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMContainers SELECT DISTINCT p.[ContainerId] FROM dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMContainerEvents] c WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMContainerEvents k ON c.[EventId]=k.[EventId] WHERE NOT EXISTS(SELECT 1 FROM #r_RMContainers x WHERE p.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckContainers SELECT DISTINCT c.[Id] FROM dbo.[CheckContainers] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMContainers k ON p.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckContainers x WHERE c.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMContainers SELECT DISTINCT p.[ContainerId] FROM dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckContainers] c WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_CheckContainers k ON c.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_RMContainers x WHERE p.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_DeliveryContainers SELECT DISTINCT c.[DeliveryId], c.[ContainerId] FROM dbo.[DeliveryContainers] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMContainers k ON p.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_DeliveryContainers x WHERE c.[DeliveryId]=x.[DeliveryId] AND c.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMContainers SELECT DISTINCT p.[ContainerId] FROM dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[DeliveryContainers] c WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_DeliveryContainers k ON c.[DeliveryId]=k.[DeliveryId] AND c.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_RMContainers x WHERE p.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMSubTransferContainers SELECT DISTINCT c.[TransferId], c.[ContainerId] FROM dbo.[RMSubTransferContainers] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMContainers k ON p.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_RMSubTransferContainers x WHERE c.[TransferId]=x.[TransferId] AND c.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_RMContainers SELECT DISTINCT p.[ContainerId] FROM dbo.[RMContainers] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[RMSubTransferContainers] c WITH(UPDLOCK,HOLDLOCK) ON c.[ContainerId]=p.[ContainerId] JOIN #r_RMSubTransferContainers k ON c.[TransferId]=k.[TransferId] AND c.[ContainerId]=k.[ContainerId] WHERE NOT EXISTS(SELECT 1 FROM #r_RMContainers x WHERE p.[ContainerId]=x.[ContainerId]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckItems SELECT DISTINCT c.[Id] FROM dbo.[CheckItems] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckSessions] p WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[Id] JOIN #r_CheckSessions k ON p.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckItems x WHERE c.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckSessions SELECT DISTINCT p.[Id] FROM dbo.[CheckSessions] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckItems] c WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[Id] JOIN #r_CheckItems k ON c.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckSessions x WHERE p.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckAudit SELECT DISTINCT c.[Id] FROM dbo.[CheckAudit] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckSessions] p WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[Id] JOIN #r_CheckSessions k ON p.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckAudit x WHERE c.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckSessions SELECT DISTINCT p.[Id] FROM dbo.[CheckSessions] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckAudit] c WITH(UPDLOCK,HOLDLOCK) ON c.[SessionId]=p.[Id] JOIN #r_CheckAudit k ON c.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckSessions x WHERE p.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckContainers SELECT DISTINCT c.[Id] FROM dbo.[CheckContainers] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckItems] p WITH(UPDLOCK,HOLDLOCK) ON c.[ItemId]=p.[Id] JOIN #r_CheckItems k ON p.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckContainers x WHERE c.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_CheckItems SELECT DISTINCT p.[Id] FROM dbo.[CheckItems] p WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[CheckContainers] c WITH(UPDLOCK,HOLDLOCK) ON c.[ItemId]=p.[Id] JOIN #r_CheckContainers k ON c.[Id]=k.[Id] WHERE NOT EXISTS(SELECT 1 FROM #r_CheckItems x WHERE p.[Id]=x.[Id]); SET @Added+=@@ROWCOUNT;
 INSERT #r_PurchaseOrders SELECT DISTINCT c.[PurchaseOrderId] FROM dbo.[PurchaseOrders] c WITH(UPDLOCK,HOLDLOCK) JOIN dbo.[InboundOrders] p WITH(UPDLOCK,HOLDLOCK) ON c.[InboundId]=p.[InboundId] JOIN #r_InboundOrders k ON p.[InboundId]=k.[InboundId] WHERE NOT EXISTS(SELECT 1 FROM #r_PurchaseOrders x WHERE c.[PurchaseOrderId]=x.[PurchaseOrderId]); SET @Added+=@@ROWCOUNT;
