CREATE TABLE #Mixed(TableName sysname,OtherProductId int);
INSERT #Mixed SELECT DISTINCT N'CheckItems',p.ProductId FROM dbo.[CheckItems] p JOIN #r_CheckItems k ON p.[Id]=k.[Id] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'DeliveryLines',p.ProductId FROM dbo.[DeliveryLines] p JOIN #r_DeliveryLines k ON p.[LineId]=k.[LineId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'InboundLines',p.ProductId FROM dbo.[InboundLines] p JOIN #r_InboundLines k ON p.[LineId]=k.[LineId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'InventoryCountItems',p.ProductId FROM dbo.[InventoryCountItems] p JOIN #r_InventoryCountItems k ON p.[ItemId]=k.[ItemId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'PickOperations',p.ProductId FROM dbo.[PickOperations] p JOIN #r_PickOperations k ON p.[PickId]=k.[PickId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'PurchaseOrderLines',p.ProductId FROM dbo.[PurchaseOrderLines] p JOIN #r_PurchaseOrderLines k ON p.[PurchaseOrderLineId]=k.[PurchaseOrderLineId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'RMContainers',p.ProductId FROM dbo.[RMContainers] p JOIN #r_RMContainers k ON p.[ContainerId]=k.[ContainerId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'RMSubRequests',p.ProductId FROM dbo.[RMSubRequests] p JOIN #r_RMSubRequests k ON p.[RequestId]=k.[RequestId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'RMSubTransfers',p.ProductId FROM dbo.[RMSubTransfers] p JOIN #r_RMSubTransfers k ON p.[TransferId]=k.[TransferId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'StockTransfers',p.ProductId FROM dbo.[StockTransfers] p JOIN #r_StockTransfers k ON p.[TransferId]=k.[TransferId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'StoragePlans',p.ProductId FROM dbo.[StoragePlans] p JOIN #r_StoragePlans k ON p.[PlanId]=k.[PlanId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'tblStock',p.ProductId FROM dbo.[tblStock] p JOIN #r_tblStock k ON p.[StockId]=k.[StockId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'tblStockTransactions',p.ProductId FROM dbo.[tblStockTransactions] p JOIN #r_tblStockTransactions k ON p.[TransId]=k.[TransId] WHERE p.ProductId<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'DeliveryPlans',COALESCE(j.productId,j.ProductIdUpper) FROM dbo.[DeliveryPlans] p JOIN #r_DeliveryPlans k ON p.[PlanId]=k.[PlanId] CROSS APPLY OPENJSON(p.Payload,'$.lines') WITH(productId int '$.productId',ProductIdUpper int '$.ProductId') j WHERE COALESCE(j.productId,j.ProductIdUpper)<>@ProductId;
INSERT #Mixed SELECT DISTINCT N'InboundPlans',COALESCE(j.productId,j.ProductIdUpper) FROM dbo.[InboundPlans] p JOIN #r_InboundPlans k ON p.[PlanId]=k.[PlanId] CROSS APPLY OPENJSON(p.Payload,'$.lines') WITH(productId int '$.productId',ProductIdUpper int '$.ProductId') j WHERE COALESCE(j.productId,j.ProductIdUpper)<>@ProductId;
