SELECT @@SERVERNAME ServerName,DB_NAME() DatabaseName,@ProductCode ProductCode,@ProductId ProductId,@Execute ExecuteMode,CASE WHEN EXISTS(SELECT 1 FROM #Mixed) THEN 0 ELSE 1 END CanExecute;SELECT * FROM #Summary WHERE RowsToDelete>0 ORDER BY TableName;SELECT * FROM #Mixed ORDER BY TableName,OtherProductId;
IF @Execute=0 BEGIN ROLLBACK;PRINT N'PREVIEW ONLY. No transaction rows or stock were deleted.';RETURN;END;
IF EXISTS(SELECT 1 FROM #Mixed) THROW 51000,N'Mixed-product documents detected. Nothing deleted. Separate those documents before reset.',1;
IF OBJECT_ID('dbo.ProductResetAudit') IS NULL CREATE TABLE dbo.ProductResetAudit(RunId uniqueidentifier PRIMARY KEY,ProductCode nvarchar(50) NOT NULL,ProductId int NOT NULL,ExecutedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ExecutedBy nvarchar(128) NOT NULL,SummaryJson nvarchar(max) NOT NULL);
IF OBJECT_ID('dbo.ProductResetBackup') IS NULL CREATE TABLE dbo.ProductResetBackup(BackupId bigint IDENTITY PRIMARY KEY,RunId uniqueidentifier NOT NULL,TableName sysname NOT NULL,RowsJson nvarchar(max) NOT NULL);
INSERT dbo.ProductResetAudit(RunId,ProductCode,ProductId,ExecutedBy,SummaryJson) SELECT @RunId,@ProductCode,@ProductId,ORIGINAL_LOGIN(),(SELECT * FROM #Summary WHERE RowsToDelete>0 FOR JSON PATH);

IF EXISTS(SELECT 1 FROM #r_CheckAudit) INSERT dbo.ProductResetBackup(RunId,TableName,RowsJson) SELECT @RunId,N'CheckAudit',(SELECT p.* FROM dbo.[CheckAudit] p JOIN #r_CheckAudit k ON p.[Id]=k.[Id] FOR JSON PATH,INCLUDE_NULL_VALUES);
IF EXISTS(SELECT 1 FROM #r_CheckContainers) INSERT dbo.ProductResetBackup(RunId,TableName,RowsJson) SELECT @RunId,N'CheckContainers',(SELECT p.* FROM dbo.[CheckContainers] p JOIN #r_CheckContainers k ON p.[Id]=k.[Id] FOR JSON PATH,INCLUDE_NULL_VALUES);
